#version 300 es
precision highp float;

// kandinsky, allegedly
// twitter.com/mattywillo_
// made for twitter.com/sableRaph's #WCCChallenge
// join the birbs nest discord to participate
// https://discord.gg/S8c7qcjw2b

// this wasn't inspired by any particular kandinsky piece
// just absorbing 2nd hand vibes from watching the stream and typing kandinsky into google
// planned to add variations but did not get around to it cmon mate its 1:36am

//also does not use processing??? sorry openprocessing ¯\_(ツ)_/¯

${shared_glsl}

in vec2 uv;
out vec4 o;

#define t time
#define nsin(v) (sin(v)*.5+.5)

vec3 circ(vec2 p, float s) {
    float d = length(p)-s;
    return vec3(p/d,d);
}

vec2 distort(vec2 p, float a, int b, int c, float d, vec2 o, float ro) {
    float f = 1./a;
    float r = length(p);
    float ph = b==0?atan(p.y,p.x):(b==1?atan(r/f):(b==2?atan(r/2.*f)*2.:b==3?r/f:(b==4?asin(r/(2.*f)*2.):asin(r/f))));
    float th = c==0?atan(p.y,p.x):(c==1?atan(r/f):(c==2?atan(r/2.*f)*2.:c==3?r/f:(c==4?asin(r/(2.*f)*2.):asin(r/f))));
    vec2 rd = vec2(sin(th)*cos(ph), sin(th)*sin(ph));

    p += o;
    p *= rot2(ro);

    return p + rd * d;
}

void main() {
    vec2 p = (uv*2.-1.)*aspect;
    vec3 col = vec3(.0);

    vec2 q = distort(p, .1*TAU + .9*TAU*nsin(t-uv.y), 0, 3, .1+nsin(t)*.3, vec2(0, sin(t)), t*-PI-p.x);
    vec3 a = circ(q, .4);
    vec3 as = smoothstep(0., fwidth(a.z), a-(sin(t-a.z*PI+length(q))*PI));
    col -= nsin(as.x-a.z) * vec3(a.x, .9, (as.x));
    col += nsin(as.y+a.z) * vec3(1.-as.y, .2, nsin(t-a.z/TAU)*.5);

    q = distort(p, .1*TAU + .2*TAU*nsin(t-uv.y), 0, 1, .1+nsin(t)*as.x, vec2(sin(t),cos(t-p.x)), 0.);
    a = circ(q, .2);
    as = smoothstep(0., fwidth(a.z), a-(sin(t-a.z*PI+length(q))*PI));
    col += nsin(as.x-a.z) * vec3(a.x, .9, pow(a.z,as.x))*as.z;

    col = pow(col,vec3(.454545));

    o = vec4(col,1);
}

// === Tab: mySketch.js ===
//ignore this lmao
//playing with some ideas for a library with glsl importing

let ratio = Math.sqrt(2);
// ratio = 1;
const flipRatio = true;
const fixedFps = 0; //useful for exporting.
const fbScale = 1.;
const fbMaxRes = 1024*2.;

const fit = (w,r=ratio) => (r<=1?[w*r,w]:[w,w/r])
const fill = (w,r=ratio) => fit(Math.max(w*r,w/r))
const scale = fill;

const srcFiles = ["shared.glsl", "march.frag", "slab.vert", "post.frag"];
const src = (await Promise.all(srcFiles.map(fn=>fetch(fn).then(r=>r.text()))))
      .map((v,i)=>[srcFiles[i].replace('.','_'),v])
      .reduce((res,[fn,src])=>({[fn]:new Function(...Object.keys(res), `return \`${src}\``)(...Object.values(res)), ...res}), {});

const canvas = document.getElementById("canvas");
const gl = canvas.getContext("webgl2", {antialias: false, preserveDrawingBuffer: true});
const app = PicoGL.createApp(canvas).clearColor(0,0,0,1);

let marchFb = app.createFramebuffer()
                   .colorTarget(0, app.createTexture2D(100,100, PicoGL.RGBA8));

const postFb = app.createFramebuffer()
                  .colorTarget(0, app.createRenderbuffer(app.width, app.height, PicoGL.RGBA8, 0));


const marchProg = app.createProgram(src.slab_vert, src.march_frag);
const postProg = app.createProgram(src.slab_vert, src.post_frag);

const slabPosVBO = app.createVertexBuffer(PicoGL.FLOAT, 2, new Float32Array([-2,0,0,-2,2,2]))
const slabVAO = app.createVertexArray().vertexAttributeBuffer(0, slabPosVBO);

const sketchUBO = app.createUniformBuffer([
  PicoGL.FLOAT_VEC2,
  PicoGL.FLOAT,
  PicoGL.INT,
])

const marchCall = app.createDrawCall(marchProg, slabVAO).uniformBlock("SketchUniforms", sketchUBO);
const postCall = app.createDrawCall(postProg, slabVAO).uniformBlock("SketchUniforms", sketchUBO).texture("tex", marchFb.colorAttachments[0]);

const debounce = (fn,to=100) => {
  let t;
  return (...a)=> { (clearTimeout(t)); t = setTimeout(_=>fn(...a), to)}
}

const resize = _ =>{
  let w = window.innerWidth;
  let h = window.innerHeight;
  if(flipRatio) ratio = (w<h&&ratio<1.)||(w>h&&ratio>1.)?ratio:1/ratio;
  w = Math.min(w, h*ratio);
  h = w/ratio;
  canvas.width = w;
  canvas.height = h
  app.resize(w,h);
  postFb.resize(w,h);
  marchFb.resize(...scale(Math.min(fbMaxRes,Math.min(w,h)*fbScale)))
  app.clear();
}
window.onresize = resize

resize()

let start,frame=0;
const step = ts => {
  if(!start) start = ts;
  frame++;
  var t = fixedFps>0 ? frame*(1/fixedFps) : (ts - start)/1000;

  sketchUBO
    .set(0, scale(1))
    .set(1, t)
    .set(2, frame)
    .update();

  app.drawFramebuffer(marchFb).clear();
  app.viewport(0,0,marchFb.width,marchFb.height);
  marchCall.draw();

  app.drawFramebuffer(postFb);
  app.viewport(0,0,postFb.width,postFb.height);
  postCall.draw();

  app.defaultDrawFramebuffer().clear();
  app.readFramebuffer(postFb).blitFramebuffer(PicoGL.COLOR_BUFFER_BIT)

  window.requestAnimationFrame(step)
}
window.requestAnimationFrame(step)


