#version 300 es

layout(location=0) in vec2 pos;

out vec2 uv;

void main() {
    uv = pos;
    gl_Position = vec4(pos*2.-1.,0,1);
}

// === Tab: post.frag ===
#version 300 es
precision highp float;

${shared_glsl}

in vec2 uv;
out vec4 o;

uniform sampler2D tex;

void main() {
    vec2 p = (uv*2.-1.)*aspect;
    o = texture(tex,uv);
}


// === Tab: shared.glsl ===
#define PI ${Math.PI.toPrecision(7)}
#define TAU ${(Math.PI*2.).toPrecision(7)}

layout(std140) uniform SketchUniforms {
    vec2 aspect;
    float time;
    int frame;
};

mat2 rot2(float a) {
  return mat2(cos(a), -sin(a), sin(a), cos(a));
}

